update todo_definition_action set action_status='APPLIED',entity_id=#{entityId}
where action_id=#{actionId} and request_fingerprint=#{requestFingerprint}
  and action_type='ACTIVATE_LEAD_RELEASE' and entity_type='LEAD_RELEASE'
  and action_status='CLAIMED' and entity_id is null
